def round_half_to_even(n):
    """
    Round the input value to `decimals` places, and pad with 0's
    if the resulting value is less than `decimals`.

    :param n:
    :return:
    """
    if isinstance(n, float):
        n_rounded = round(n, 5) if n.is_integer() else round(n, 5)
        if n_rounded < 2:
            return str(int(n_rounded))  # If rounded value is less than 2, return an integer str
        if n_rounded % 2 == 0:
            return str(n_rounded)  # If rounded value is even, return as is
        else:
            return str(int(n_rounded) + 1)  # If rounded value is odd, round up and return as is
    else:
        raise ValueError("Input must be a number")

