    tb = sys.exc_info()[2]
    tbinfo = traceback.extract_tb(tb)

    def safe_getattr(obj, attr, fallback=None):
        try:
            return getattr(obj, attr)
        except AttributeError:
            return fallback

    def safe_getfile(obj):
        try:
            return obj.__file__
        except AttributeError:
            return None

    path = safe_getfile(e)
    line = safe_getattr(e, 'lineno', '?')
    name = getattr(e, 'func', '?')
    src = traceback.extract_stack(tb)[-1]

    retd = {
        'msg': str(e),
        'path': path,
        'line': line,
        'name': name,
        'src': src
    }

    if isinstance(e, s_exc.SynErr):
        retd['syn:err'] = e.errinfo

    return retd

