def _legacy_mergeOrderings(orderings):
    res = []
    for idx in range(len(orderings[0])):
        suffixes = set()
        for o in orderings:
            if len(o) > idx:
                suffixes.add(o[idx])
        res.append(suffixes)
    return res

def _legacy_mergeOrderings(orderings):
    orderings_map = {}  # Dictionary to map an object to its suffix to follow
    for ordering in orderings:
        for i in range(len(ordering) - 1):
            needy_val = ordering[i]
            needs_suffix = ordering[i + 1:]

            # Set a resultant suffix for needing_val if it doesn't exist
            if needy_val not in orderings_map:
                orderings_map[needy_val] = needs_suffix

            # Make the suffix of needy_val re-use needs_suffix
            elif orderings_map[needy_val] != needs_suffix:
                for element in needs_suffix:
                    orderings_map[element] = needs_suffix

    result = []
    for ordering in orderings:
        current = ''
        has_next = True
        while has_next:
            has_next = False
            for needy_val, needs_suffix in sorted(orderings_map.items(), key=lambda x: ordering.index(x[0])):
                offset = ordering.index(needy_val)
                if offset == 0:
                    current += needy_val + needs_suffix[:-1]
                elif offset == len(ordering) - 1:
                    current += needs_suffix[1:]
                else:
                    current += needy_val + '0' * (len(ordering) - offset - 1) + needs_suffix[1:]
                has_next = len(needs_suffix) > 0
                orderings_map[needy_val] = needs_suffix[1:]
            if current:
                result.append(current)

    return result

