def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    seen = set()
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        yield cls.__dict__

def minimalBases(classes):
    if not classes:
        return []
    seen = set(classes)
    while True:
        new_seen = set()
        for cls in seen:
            if cls in new_seen or not cls.__bases__:
                continue
            new_seen.add(cls)
            for b in minimalBases(cls.__bases__):
                if b in seen:
                    continue
                new_seen.add(b)
        if new_seen == seen:
            break
        seen = new_seen
    return list(seen)

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    return list(sorted(classes))

