def _c_optimizations_available(self):
        """
        Return the C optimization module, if available, otherwise
        a false value.

        If the optimizations are required but not available, this
        raises the ImportError.

        This does not say whether they should be used or not.
        """
        optimizations_modules = {
            'bfgs': '_bfgs',
            'lbfgs': '_lbfgs',
            'scipyfmin': '_scipyfmin',
        }

        module_name = optimizations_modules.get(self.name.lower())
        if module_name:
            try:
                return __import__(module_name)
            except ImportError:
                raise ImportError("The '{}' C optimization module is not available.".format(self.name))
        else:
            raise ValueError("Invalid optimization name: '{}'".format(self.name))

