def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if coord_name not in self.coords:
        logger.error(f"Coordinate '{coord_name}' not found.")
        return []
    coords = self.coords[coord_name]
    if not coords.stale:
        return None
    err_indices = []
    for i, value in enumerate(coords.data):
        if not np.isnan(value):
