def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion, set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or level < 0:
        result = {}
        for key, value in d1.items():
            if key not in d2:
                result[key] = value
        return result
    elif level == 0:
        result = {}
        for key, value in d1.items():
            if key in d2 and value != d2[key]:
                result[key] = value
        return result
    else:
        result = {}
        for key, value in d1.items():
            if key not in d2:
                result[key] = value
            elif isinstance(value, dict):
                recursive_result = difference(value, d2[key], level - 1)
                if recursive_result:
                    result.update(recursive_result)
            elif isinstance(value, np.ndarray):
                np.testing.assert_array_equal(value, d2[key])
            elif value != d2[key]:
                result[key] = value
        return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.

    """
    if level == -1:
        return set(d1.items()).difference(set(d2.items()))
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2 or (isinstance(v, dict) and d2[k] != v):
                if level > 1:
                    if k not in result:
                        if isinstance(v, dict):
                            result[k] = {}
                            result[k] = difference(v, {}, level - 1)
                        else:
                            result[k] = v
                    else:
                        if isinstance(v, dict):
                            if isinstance(result[k], dict):
                                difference(v, result[k], level - 1)
                            else:
                                result[k] = difference(v, {}, level - 1)
                        else:
                            if isinstance(result[k], dict):
                                if not isinstance(result[k].get(k, {}), dict):
                                    result[k] = {k: result[k]}
                                    result[k] = difference(v, result[k], level - 1)
                                else:
                                    result[k] = difference(v, result[k].get(k, {}), level - 1)
                            else:
                                result[k] = v
        return result

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    diff = {}
    if level == -1:
        for k in d1:
            if k in d2 and d1[k] != d2[k]:
                diff[k] = {k:d1[k]}
        for k in d2:
            if k in d1 and d1[k] != d2[k]:
                diff[k] = {k:d2[k]}
    elif level == 1:
        for k in d1:
            if k in d2 and d1[k] != d2[k]:
                diff[k] = {k:d1[k]}
        for k in d2:
            if k in d1 and d1[k] != d2[k]:
                diff[k] = {k:d2[k]}
            elif isinstance(d1[k], dict) and isinstance(d2[k], dict):
                diff[k] = difference(d1[k], d2[k], level=1)
            elif isinstance(d1[k], list) and isinstance(d2[k], list):
                diff[k] = difference(d1[k], d2[k], level=1)
            elif isinstance(d1[k], set) and isinstance(d2[k], set):
                diff[k] = difference(d1[k], d2[k], level=1)
            elif isinstance(d1[k], tuple) and isinstance(d2[k], tuple):
                diff[k] = difference(d1[k], d2[k], level=1)
            else:
                diff[k] = {k:d1[k]}
    elif level > 0:
        for k in d1:
            if k in d2 and d1[k] == d2[k]:
                continue
            if k in d2 and isinstance(d2[k], dict):
                diff[k] = difference(d1[k], d2[k], level=level-1)
            elif k in d2 and isinstance(d2[k], list):
                diff[k] = difference(d1[k], d2[k], level=level-1)
            elif k in d2 and isinstance(d2[k], set):
                diff[k] = difference(d1[k], d2[k], level=level-1)
            elif k in d2 and isinstance(d2[k], tuple):
                diff[k] = difference(d1[k], d2[k], level=level-1)
            else:
                diff[k] = {k:d1[k]}
    else:
        raise ValueError("Level must be greater than or equal to 0")
    return diff

