def fill(self, coord, weight=1):
    if not self.edges:
        raise ValueError("Histogram has no edges")
    if not self.weights:
        raise ValueError("Histogram has no weights")
    if not isinstance(coord, (tuple, list, np.ndarray)):
        raise ValueError("coord must be a tuple, list, or numpy array")
    try:
        # Convert coord to index
        index = [int(round((val - edge) / self.bin_width)) 
                 for coord, edge, bin_width in zip(coord, self.edges, self.bin_widths)]

        if any(i < 0 or i >= len(self.hist) for i in index):
            print(f"Skipping coordinates {coord} because they are outside the histogram edges.")
            return
        # Fill histogram
        self.hist[index] += weight
    except Exception as e:
        print(f"Error filling histogram at {coord}: {e}")

def fill(self, coord, weight=1):
  # Check if coord is within the range of the histogram's edges
  if coord < (self.edges - 1)[0] or coord > self.edges[-2]:
      raise ValueError("Coordinate outside the histogram range")

  # Find the bin index the coordinate falls into
  for i in range(len(self.edges) - 1):
    if coord >= self.edges[i] and coord < self.edges[i + 1]:
      # Add the weight to the corresponding bin
