def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.min_coord or coord > self.max_coord:
        return

    index_x = int((coord - self.min_coord) / self.bin_width)
    try:
        self._hist[index_x] += weight
    except IndexError:
        pass

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not self.edges or not self.weights:
        raise RuntimeError("Histogram is new and needs pre-setting edges and weights.")

    bin_index = np.searchsorted(self.edges, coord, side='right') - 1
    if bin_index < 0 or bin_index >= len(self.edges) - 1:
        return

    self.weights[bin_index] += weight

