def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    sql_statement = sql
    if self.params.is_out_style:
        params_list = []
        for params in many_params:
            params_list.append(self._convert_out_style(params))
        sql_statement, new_params = self.concatenate_sql_with_additional_values(sql, params_list)
    else:
        for params in many_params:
            sql_statement, new_params = self.concatenate_sql_with_additional_values(sql, params)
    return sql_statement, new_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    sql_params = { param: value for param, value in many_params[0].items() }
    formatted_sql = sql

    inserted_params = []
    for params in many_params:
        inserted_params.append({})
        for key, value in params.items():
            placeholder = formatted_sql.index(key)
            if placeholder == -1 or SQLParams.in_style == "named":
                formatted_sql = formatted_sql.replace(key, f":{key}")
            else:
                placeholder += 1
                formatted_sql = formatted_sql[:placeholder] + f":{placeholder}" + formatted_sql[placeholder:]

        inserted_params[-1] = sql_params.copy()
        for key, value in inserted_params[-1].items():
            param_index = formatted_sql.index(f":{key}")
            sql = sql[:param_index] + str(value) + sql[param_index + len(f":{key}"):]

    return formatted_sql, inserted_params

