def add_asset(self, basename, file_path):
    """
    This method adds a file to the repository and organizes it correctly based on the basename. It uses file path to determine the correct directory and creates the necessary entries in both the repository index and the collection index. It also handles potential errors by logging and raising exceptions for invalid inputs or specific issues.

    Args:
        basename (str): The basename of the file (e.g., "artigo02-gf03").
        file_path (str): The full path from which the file will be copied and organized.

    Returns:
        None

    Raises:
        FileNotFoundError: If the provided file path does not exist.
        IOError: If an error occurs during the copying or organization process.
        ArtifactAlreadyExistsError: If an artifact with the same basename already exists in the repository.
    """
    try:
        # Check if the file path exists
        if not os.path.exists(file_path):
            raise FileNotFoundError(
                u("The file path '{0}' does not exist.").format(file_path)
            )

        # Split the file into directory and file name
        directory, file_name = os.path.split(file_path)

        # Create the directory if it doesn't exist
        if not os.path.exists(directory):
            os.makedirs(directory)

        # Create a new entry in the repository index
        asset_id = self.create_asset(
            {
                'title': file_name,
                'location': file_path
            }
        ).get_id()

        # Create an entry in the collection index (if applicable)
        collection_id = self.create_collection(
            {
                'title': file_name.split('.')[0],
                'artifacts': [asset_id]
            }
        ).get_id()

        # Log the successful addition
        logger.info(
            u("Asset added: '{0}' ({1})").format(file_name, directory)
        )

    except FileNotFoundError as e:
        logging.exception(e)
        raise FileNotFoundError(
            u("Error adding asset: %s") % e
        )

    except IOError as e:
        logging.exception(e)
        raise IOError(
            u("Error adding asset: %s") % e
        )

    except ArtifactAlreadyExistsError as e:
        logging.exception(e)
        raise ArtifactAlreadyExistsError(
            u("Artifact already exists: %s") % e
        )

