def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    class PrettyPrinter:
        def __init__(self, indent):
            self.indent = indent

        def _format(self, node):
            if isinstance(node, list):
                return '\n'.join(self._format(item) for item in node)
            elif isinstance(node, dict):
                return '\n'.join('{}{}: {}'.format(
                    self.indent, key, self._format(value))
                    for key, value in node.items())
            elif isinstance(node, str):
                return self.keyval(node, indent)
            else:
                return str(node)

        def keyval(self, node, indent):
            if debug:
                return 'keyval debug({}, {})'.format(node, indent)
            return '{}\'{}\''.format(self.indent, node)

    return PrettyPrinter(indent)(self).__format__()

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    if debug:
        for attr in dir(self):
            val = getattr(self, attr)
            print(f"{attr}: {val}")
    return str(self)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    if not hasattr(self, '__dict__'):
        return str(self)
    pretty_attrs = [(k, pretty(v, indent + 2, debug)) for k, v in sorted(self.__dict__.items(), key=lambda x: x[0])]
    line_prefix = ' ' * indent + ': '
    pretty_printed_attrs = '\n'.join(f"{k}{line_prefix}{v}" for k, v in pretty_attrs)
    if debug:
        pretty_set_attrs = ['\'' + str(k) + '\'' for k in sorted(self.__dict__.keys(), key=lambda x: len(x))]
        return '{\n' + pretty_printed_attrs + '\n' + ',\n'.join(f"  {k}" for k in pretty_set_attrs) + '\n}\n'
    return '{\n' + pretty_printed_attrs + '\n}\n'

class HookRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, event, func):
        if not callable(func):
            raise TypeError("The provided function should be callable.")
        if event in self._registry:
            raise KeyError(f"Hook '{event}' already exists in the registry.")
        self._registry[event] = func

    def add_handler(self, event, func):
        if not callable(func):
            raise TypeError("The provided function should be callable.")
        if event not in self._registry:
            raise KeyError(f"Hook '{event}' does not exist in the registry.")
        self._registry[event].append(func)

