class Client:
    def __init__(self):
        self._registry = {}

    def add_handler(self, event: str, func: Callable):
        if event in self._registry:
            print(f"Handler for event '{event}' already exists.")
            return
        self._registry[event] = func

    def handle(self, event: str) -> Callable:
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.

        """
        def dec(func: Callable):
            if event in self._registry:
                print(f"Handler for event '{event}' already exists.")
                return
            self.add_handler(event, func)
            return func
        return dec

def _fromutc(self, dt):
        # clone to avoid modifying the original
        dt_copy = dt.replace(tzinfo=None)
        # extract original offset
        original_offset = dt_copy.utcoffset()
        if original_offset is None:
            raise ValueError("The input datetime must not be time-naive")
        # calculate the raw utc timestamp
        raw_utc_timestamp = dt_copy.timestamp() - original_offset.total_seconds()
        return datetime.utcfromtimestamp(raw_utc_timestamp, self.timezone)

def normalized(self):
        # Convert float to integer in case a rounding error exists
        rounded_days = int(self.days)
        rounded_hours = int(self.hours)

        # Handle rare case where hours exceed days
        if rounded_hours + 24 > rounded_days:
            rounded_days += 1
            rounded_hours -= 24

        return relativedelta(days=rounded_days, hours=rounded_hours)

