def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version == "0.0.0" or not version:
        return "1.0.0"

    parts = version.split('.')
    if parts[0] == "0":
        new_parts = [str(int(parts[1]) + 1), "0", "0"]
    else:
        new_parts = [str(int(parts[0]) + 1), "0", "0"]

    return '.'.join(new_parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    return '{:04d}'.format(int(version) + 1)

def next_version(version):
    if not version:
        raise ValueError("Version cannot be None")

    if version[0].isdigit():
        # Handle zero-prefixed versions
        num = int(version)
        if num + 1 < 10:
            return f"0{num + 1}"
        else:
            return f"{num + 1}"
    else:
        # Handle non-zero prefixed versions
        parts = version.split(".")
        if len(parts) < 2:
            raise ValueError("Version string must contain a major and minor version")

        major = int(parts[0])
        minor = int(parts[1])
        if minor + 1 < 10:
            return f"{major}.{minor + 1}"
        else:
            return f"{major}.{minor + 1}0"

