    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    ahead = []
    content_hash = None
    for version in version_dirs:
        if not isinstance(version, str):
            raise TypeError('version_dirs must be an array of version directory names.')

        if content_hash and content_hash != PACKAGING_CONTENT_HASH:
            raise ValueError(f'Content hash changed from the previous version: {content_hash} to {PACKAGING_CONTENT_HASH}.')

        try:
            spec = SpecifierSet(version)
            ahead.append((version, spec))
        except packaging.specifiers.InvalidSpecifier as error:
            tmpl = (
                "Version '{version}' in version_dirs is not a valid version specifier; {error}"
            )
            raise DistutilsSetupError(tmpl.format(version=version, error=error))

    return ahead

