        for version in version_dirs[1:]:
            inventory = self.inventories.get(version)
            if not inventory:
                raise ValueError(f'Inventory for version {version} not found.')
            if prev_version != inventory.version:
                raise ValueError(f'Expected inventory for version {prev_version} but got {inventory.version}.')
            if inventory == expected_inventory:
