def find_path_type(path):
    if not path.startswith('root/') or not path.startswith('object/'):
        return 'error: Path does not start with "root/" or "object/"'

    for part in path.split('/'):
        if part.startswith('0=*'):
            return 'file'

    return 'error: No 0=* namaste found'

