        requests.append({'uri': f'bug/{bug_id}', 'method': 'PUT', 'json': bug_params})
    Responses = self.request('/bug', 'POST', json=dict(requests=responses))
    if 'error' not in Responses:
        updated_bugs = Responses['bugs']
        for bug in updated_bugs:
