def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    # This solution is a Python implementation of the deep merge algorithm described
    # in the task description. The function iterates through the input list of tuples,
    # using the `copy.deepcopy` function to handle nested mappings. If a duplicate key
    # is found, and the node associated with the key is of type `MappingNode`,
    # the current node's value is updated with the value of the existing node.
    # If the key is found but the node is not of type `MappingNode`, the last
    # matching node's value is retained. If a conflicting key is encountered without
    # a matching value, the function raises an exception.
    if not nodes:
        return []
    unique_values = {}
    for node in nodes:
        key, value = node
        if key in unique_values:
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(unique_values[key], ruamel.yaml.nodes.MappingNode):
                unique_values[key].merge(value)  # Use python's built-in merge for nested mapping nodes
            else:
                unique_values[key] = value
        else:
            unique_values[key] = value
    return unique_values.values()

def deep_merge_nodes(nodes):
    merged_dict = dict()
    for key, value in nodes:
        if key in merged_dict:
            if isinstance(value, dict) and isinstance(merged_dict[key], dict):
                merged_dict[key] = deep_merge_nodes([(key, val) for key, val in value.items() + merged_dict[key].items()])
            elif isinstance(merged_dict[key], list) and isinstance(value, list):
                merged_dict[key].extend(value)
            else:
                merged_dict[key] = value
        else:
            merged_dict[key] = value
    return merged_dict

def deep_merge_nodes(nodes):
    merged_dict = defaultdict(dict)
    for key, value in nodes:
        if key in merged_dict:
            if isinstance(value, dict) and isinstance(merged_dict[key], dict):
                merged_dict[key] = deep_merge_nodes([
                    (k, v) for (k, v) in value.items()
                    if k in merged_dict[key] or k not in merged_dict[key]
                ])
            elif isinstance(value, (int, str)) and isinstance(merged_dict[key], (int, str)):
                merged_dict[key] = value
        else:
            merged_dict[key] = value
    return list(merged_dict.items())

