                    if parser_name.dest == 'repository':
                        arg_dct[name] = args.repository
                found = True
                break
        if not found:
            print(f"Unknown argument: {arg}")
    return arg_dct, remain_args

def deep_merge_nodes(nodes):
    # Use a dictionary to map each key to its corresponding values.
    merged_dict = {}

    for key, value in nodes:
        # If the key already exists, we have a conflict.
        if key in merged_dict:
            # Flatten and merge the values if they are ListNodes.
            if isinstance(merged_dict[key], dict) and isinstance(value, dict):
                if isinstance(merged_dict[key].get('value'), list) and isinstance(value.get('value'), list):
                    merged_dict[key]['value'].extend(value['value'])
            else:
                merged_dict[key].append(value)
        # Otherwise, we simply store the value.
        else:
            merged_dict[key] = value

    # Convert the dictionary back to a list of tuples.
    merged_nodes = [(key, value) for key, value in merged_dict.items()]

    return merged_nodes

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    node_dict = {}
    for key, value in nodes:
        if key in node_dict:
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(node_dict[key], ruamel.yaml.nodes.MappingNode):
                deep_merge_nodes([(key, value), (key, node_dict[key])])
            elif isinstance(value, ruamel.yaml.nodes.SequenceNode) and isinstance(node_dict[key], ruamel.yaml.nodes.SequenceNode):
                node_dict[key].extend(value)
            else:
                node_dict[key] = value
        else:
            node_dict[key] = value

    return list(node_dict.items())

def deep_merge_nodes(nodes):
    from typing import Any, List, Tuple
    from ruamel.yaml.nodes import Node, ScalarNode, MappingNode

    combined_dict = {}
    for key, value in nodes:
        if key not in combined_dict:
            combined_dict[key] = value
        else:
            if isinstance(value, ScalarNode):
                combined_dict[key] = value
            elif isinstance(value, MappingNode):
                if not combined_dict[key]:
                    combined_dict[key] = value
                else:
                    combined_dict[key].update(value)
    return combined_dict

