def bash_completion():
    cli = click.Command(borgmatic.cli)
    ctx = click.Context(cli)

    class BashCompletionPrinter(PrinterABC):
        @call
        def print_header(self):
            pass

        @call
        def print_completions(self, completions: List[str]):
            pass

    with ctx:
        buf, printer = get_temporary_file_name('bash_completion_', suffix='.sh')
        try:
            cli.main(ctx, no_args_is_help=True)
        except Exception as e:
            cli.main(ctx, no_args_is_help=True)
            printer.print_error(e)
            return

        method = cli.command.completion(ctx)
        if method:
            code = method()
            completion = []
            for match in re.findall(r'\$[\w\.]+', code):
                if '.' not in match:
                    path = '\`${match}`${match.replace('.', '/')}`;
                    if path and path.startswith('${BORG_CACHE}'):
                        path = path.split('${BORG_CACHE}', 1)[1]
                    path = path.replace('/', '.')[:-1]
                    completion.append(path)
            printer.print_header()
            printer.print_completions(completion)
            with open(buf, 'rb') as f:
                click.echo(f.read())
        else:
            click.echo('# No bash completion available')

