def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Regular expression to identify custom string URL items
    url_pattern = r'\{[a-zA-Z0-9_]+}\}'
    matches = re.findall(url_pattern, url)

    # Iterate over matches and replace them with values from args
    for match in matches:
        variable = re.sub(r'\{|}', '', match)
        if variable in url_args:
            url = re.sub(match, str(url_args[variable]), url)
        else:
            logger.warning(f'Error: Variable {variable} not found in url arguments')

    return url

