def make_find_paths(find_paths):
    def is_glob_pattern(path):
        return path.startswith('pp:') or '*' in path

    result = []
    for item in find_paths:
        if is_glob_pattern(item):
            # Apply globbing rules for paths starting with 'pp:'
            if item.startswith('pp:root/'):
                base_path = item[len('pp:root/'):]
                pattern = f"sh:{base_path}*"
            elif item.startswith('pp:glob/'):
                base_path = item[len('pp:glob/'):]
                pattern = f"sh:{base_path}**/*"
            else:
                pattern = item
            result.append(pattern)
        else:
            result.append(item)
    return result

