def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Check for invalid inputs
    if not isinstance(commands, list):
        raise TypeError("commands must be a list")

    for command in commands:
        if not isinstance(command, str):
            raise TypeError("All elements in commands must be strings")

    if not isinstance(args, list):
        raise TypeError("args must be a list")

    for arg in args:
        if not isinstance(arg, str):
            raise TypeError("All elements in args must be strings")

    # Convert arguments to a list if not already
    if not isinstance(env, dict):
        env = {}
    if not isinstance(cwd, str):
        cwd = None

    # Construct the command to be executed
    full_command = [command] + args
    full_command += ['- executable:', repr(full_command)]

    # Run the command using subprocess.run
    if verbose:
        print(f"Executing command: {' '.join(full_command)}")

    try:
        result = subprocess.run(full_command, cwd=cwd, env=env, capture_output=True, text=True, errors="ignore")

        if hide_stderr:
            result.stderr = ""

        return result
    except subprocess.CalledProcessError as e:
        print(f"Command failed: {e}")
        return None

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    try:
        if verbose:
            print(f"Running commands: {commands} with args: {args} directory: {cwd} environment: {env}")
        if hide_stderr:
            hide_stderr = subprocess.DEVNULL
        else:
            hide stderr = subprocess.STDOUT      

        p = subprocess.Popen(commands, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, cwd=cwd, env=env)
        stdout, stderr = p.communicate()

        if verbose and not hide_stderr:
            print(f"ScriptExecutionError: {stderr}")

        if p.returncode != 0:
            raise subprocess.CalledProcessError(p.returncode, f"Command failed with exit code {p.returncode}")

        return stdout

    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(e.returncode, f"Command failed with exit code {e.returncode}")

    except Exception as e:
        raise ValueError("An error occurred", str(e))

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    for command in commands:
        try:
            result = subprocess.run(command + args, cwd=cwd, verbose=verbose, hide_errors=hide_stderr,
                                   capture_output=True, env=env)
            if result.returncode != 0:
                if verbose:
                    print(f"Error running command: {command + args}")
                    print(f"Return code: {result.returncode}", file=sys.stderr)
                raise subprocess.CalledProcessError(result.returncode, command + args)
            if verbose:
                print(f"Command {command + args} succeeded.")

        except Exception as e:
            if verbose:
                print(f"An error occurred while running command: {command + args}")
                print(str(e), file=sys.stderr)
            raise

