def find_roots(graph, prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    def add_parents(parent, node_set):
        if parent not in node_set:
            node_set.add(parent)
            for parent_of_parent in graph.direct_successors(parent):
                add_parents(parent_of_parent, node_set)

    all_roots = set()

    for node in graph.nodes():
        seen = set()
        parents = {graph.predecessors(node)[0]}
        add_parents(node, seen)

        if node in seen and len(seen) == 1:
            all_roots.add(node)

    return all_roots

def find_roots(self, graph, prop, roots=None):
    if props is None:
        props = [rdflib.RDFS.subClassOf]

    if roots is None:
        roots = set()

    def visit(node):
        if node not in visited:
            visited.add(node)
            for child in node.children:
                visit(child)

    visited = set()
    visited = set(roots)

    for prop in props:
        for subject, predicate, obj in graph.triples((None, prop, None)):
            if obj not in visited:
                visit(obj)

    return visited

def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    roots_changed = False

    for sub_class in graph.subjects(prop):
        if sub_class not in roots:
            roots.add(sub_class)
            roots_changed = True

    while roots_changed:
        roots_changed = False

        for sub_class in roots:
            if any(pred != prop for pred, _, _ in list(graph.triples((sub_class, None, None)))):
                continue

            new_sub_class = [sub_pred for sub_pred, _, _ in graph.triples((sub_class, None, None)) if sub_pred != prop]
            for pred, obj in list(graph.triples((new_sub_class, prop, None))):
                if obj not in roots:
                    roots.add(obj)
                    roots_changed = True

    return roots

def find_roots(graph, prop, roots=None):
  if roots is None:
    roots = set()

  for child, _, parent in graph.triples((None, prop, None)):
    if parent not in roots:
      roots.add(parent)

  return roots

