def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    sigma = 0.1
    return np.exp(-(x - 0.2) ** 2 / (2 * sigma ** 2)) / (np.sqrt(2 * np.pi) * sigma)

