def _verify(iface, candidate, tentative=False, vtype=None):
    if tentative:
        return True

    # Check if candidate claims to provide the interface
    if not iface.providedBy(candidate):
        raise ConflictingNames("%s does not provide %s" % (candidate, iface))

    # Get all necessary methods and attributes of the candidate
    methods = [attr for attr in dir(candidate) if callable(getattr(candidate, attr))]
    attributes = [attr for attr in dir(candidate) if not callable(getattr(candidate, attr))]

    # Check for methods
    for method in methods:
        method_interface = getattr(candidate, method).im_class.providedBy(iface)
        if isinstance(method_interface, zope.interface.NotFound):
            raise ConflictingNames("%s does not provide %s" % (candidate, iface))
        elif isinstance(method_interface, zope.interface.implements):
            impls = method_interface.implementedBy()
            if len(impls) > 1:
                raise ConflictingNames("%s provides %s, but %s implements %s"
                                        % (candidate, iface, candidate, impls))
            elif len(impls) == 1:
                impl = impls[0]
                if not issubclass(impl, iface.im_class):
                    raise ConflictingNames("%s provides %s, but it does not implement %s"
                                            % (candidate, iface, candidate, iface.im_class))

    # Check for attributes
    for attr in attributes:
        attr_interface = getattr(candidate, attr).im_class.providedBy(iface)
        if isinstance(attr_interface, zope.interface.NotFound):
            raise ConflictingNames("%s does not provide %s" % (candidate, iface))
        elif isinstance(attr_interface, zope.interface.implements):
            impls = attr_interface.implementedBy()
            if len(impls) > 1:
                raise ConflictingNames("%s provides %s, but %s implements %s"
                                        % (candidate, iface, candidate, impls))
            elif len(impls) == 1:
                impl = impls[0]
                if not issubclass(impl, iface.im_class):
                    raise ConflictingNames("%s provides %s, but it does not implement %s"
                                            % (candidate, iface, candidate, iface.im_class))

    # If no errors have been raised, return True
    return True

