def _checkConflictingNames(interfaces):
    """
    Raise an exception if any of the names present in the given interfaces
    conflict with each other.

    @param interfaces: a list of Zope Interface objects.

    @return: None

    @raise ConflictingNames: if any of the attributes of the provided
    interfaces are the same, and they do not have a common base interface which
    provides that name.
    """
    names = {}
    for interface in interfaces:
        for name in interface:
            if name in names:
                otherInterface = names[name]
                parent = _commonParent(interface, otherInterface)
                if parent is None or name not in parent:
                    raise ConflictingNames("%s conflicts with %s over %s" % (
                            interface, otherInterface, name))
            names[name] = interface

def inducingpoint_wrapper(feat, Z):
    """
    Models which used to take only Z can now pass `feat` and `Z` to this method. This method will
    check for consistency and return the correct feature. This allows backwards compatibility in
    for the methods.
    """
    if feat is not None and Z is not None:
        raise ValueError("Cannot pass both an InducingFeature instance and Z values")  # pragma: no cover
    elif feat is None and Z is None:
        raise ValueError("You must pass either an InducingFeature instance or Z values")  # pragma: no cover
    elif Z is not None:
        feat = InducingPoints(Z)
    elif isinstance(feat, np.ndarray):
        feat = InducingPoints(feat)
    else:
        assert isinstance(feat, InducingFeature)  # pragma: no cover
    return feat

def _TypecheckDecorator(subject=None, **kwargs):
  """Dispatches type checks based on what the subject is.

  Functions or methods are annotated directly. If this method is called
  with keyword arguments only, return a decorator.
  """
  if subject is None:
    return _TypecheckDecoratorFactory(kwargs)
  elif inspect.isfunction(subject) or inspect.ismethod(subject):
    return _TypecheckFunction(subject, {}, 2, None)
  else:
    raise TypeError()

def validate(key, value, specifications):
    """
    Intended for use within deconstruct validator dict,
    key is attribute name
    value is dictionary for that attribute
    specifications is dictionary of specifications
    """
    for key, val in specifications.items():
        spec = val[key]
        if isinstance(spec, dict):
            base_type, for_type = spec.values()
            if isinstance(value, dict) and key in value and isinstance(value[key], base_type):
                for name, val in value[key].items():
                    if isinstance(val, dict) and key in val and isinstance(val[key], for_type):
                        validate(name, val, spec)
                    elif isinstance(val, for_type):
                        pass
                    else:
                        raise Invalid("Invalid %s type for %s in %s" % (for_type.__name__, key, name))
            else:
                raise Invalid("Invalid %s type for %s in %s" % (spec, key, value))
        elif isinstance(value, spec):
            pass
        else:
            raise Invalid("Invalid %s type for %s in %s" % (spec, key, value))

