def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    obj = sandbox.ObjectType(iface.__name__)
    obj['templates'] = {}
    obj['methods'] = []
    obj['defaults'] = []
    obj['parameters'] = []
    obj['value'] = None

    # try to use the __new__ function of the candidate
