        try:
            obj.value = candidate.__new__()
        except Exception as e:
            error_message = 'Failed to create object for {}: {}'.format(iface.__name__, str(e))
            raise RuntimeError(error_message)

    if not tentative and hasattr(candidate, '__init__'):
        try:
