                if isinstance(baseobj, ClassDef) and baseobj.hide:
                    return baseobj.type
        except exceptions.InferenceError:
            pass
    return object

def determine_metaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    explicit_meta = None if explicit_mc is None else explicit_mc
    for base in bases:
        if not IsInstantiable(base):
            continue
        metaclass = GetMetaclass(base)
        if metaclass is not None:
            explicit_meta = metaclass
            break
    return explicit_meta

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    specificMeta = None
    if not explicit_mc:
        for base in bases:
            if base.__name__.startswith('_'):
                continue
            obj = base.infer()
            if isinstance(obj, ClassDef) and isinstance(obj.body[0], BaseNode):
                if not specificMeta:
                    specificMeta = obj.body[0].metaclass

    else:
        specificMeta = explicit_mc

    return specificMeta

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    for base in reversed(bases):
        if base and isinstance(base, class_def.ClassDef) and not base.self_modification():
            break

    metaclass = base.metaclass() if base else explicit_mc

    if metaclass:
        return (type(bases), (metaclass, bases))

    for base in reversed(bases):
        if base and isinstance(base, class_def.ClassDef):
            class_obj = base.infer()
            if class_obj and class_obj.__class__ in (class_def.ClassDef, class_def.TypeDef, class_def.ForwardTypedef):
                metaclass = type(class_obj)
                return (type(bases), (metaclass, bases))

    for base in reversed(bases):
        if base and isinstance(base, class_def.ClassDef) and base.self_modification():
            metaclass = base._metaclass
            if isinstance(metaclass, class_def.ClassDef) and not metaclass.self_modification():
                break

    metaclass = base._metaclass if base and isinstance(base, class_def.ClassDef) and not base.self_modification() else explicit_mc

    if metaclass:
        return (type(bases), (metaclass, bases))

    return None

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default

def pop(self, key, default=__marker):
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                    self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self._redis.get(key)
        self._redis.delete(key)
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""

        if not self._head or not self._tail:
            raise KeyError('list is empty')

        least_used_node = self._head
        for node in self._head[2:]:
            if node[2] < least_used_node[2]:
                least_used_node = node

        self._remove(least_used_node)
        return (least_used_node[0], least_used_node[1][0])

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._counter:
        raise KeyError("dictionary is empty")

    unused_items = []
    keys = self._items.keys()
    for key in keys:
        if key not in self._counter:
            unused_items.append((key, self._counter[key]))

    least_frequent = min(unused_items, key=lambda x: x[1])
    key, count = least_frequent
    self._items.pop(key)
    self._counter.pop(key)
    self._pop_count += 1

    return (key, self._items[key][0])

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # Find the minimum frequency key-value pair
        min_freq = min(self.freq_map.values())
        min_freq_items = [(k, v) for k, v in self.freq_map.items() if v == min_freq]
        # Choose one of the minimum frequency items randomly
        if min_freq_items:
            item = random.choice(min_freq_items)
            del self.freq_map[item[0]]
            del self.cache[item[0]]
            return item
        else:
            raise KeyError('no elements in the cache')
    except KeyError, e:
        raise BadRequestKeyError(str(e))

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""

    lattice_client = self.get_lattice_client()
    least_used_key_value = lattice_client.get_least_used_key_value()

    if least_used_key_value:
        key, value = least_used_key_value
        self.delete_key(key)
        return (key, value)
    else:
        raise KeyError("No least used key-value pair found.")

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self or not self._data:
        raise KeyError('dictionary is empty or empty')
    return list(self._data.items())[0]

def popitem(self, last=True):
        """Remove and return the `(key, value)` pair least recently used."""
        if last:
            pop_item = self._dict.popitem(last=True)
            return pop_item
        else:
            pop_item = self._dict.popitem(last=False)
            return pop_item

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self._head[2]:
        raise KeyError('list is empty')
