def isoparse(self, dt_str):
    match = re.match(r'^(?P<year>\d{4})(-(?P<month>\d{2})(-(?P<day>\d{2}))?T(?P<hour>\d{2}):(?P<minute>\d{2}):(?P<second>\d{2})(?:\.(?P<microsecond>\d+$))?(?P<timezone>Z|[+-]\d{2}:\d{2})?$', dt_str)
    if not match:
        raise ValueError(f"Invalid ISO-8601 datetime format: {dt_str}")

    groups = match.groupdict()
    year, month, day = map(int, [groups['year'], groups.get('month'], groups.get('day')])
    hour, minute, second = map(int, [groups['hour'], groups.get('minute'), groups.get('second')])
    microsecond = int(groups.get('microsecond', 0))
    timezone_str = groups.get('timezone', '+00:00')

    if timezone_str == 'Z':
        tz = UTC()
    elif timezone_str.startswith('+') or timezone_str.startswith('-'):
        hours, minutes = map(int, timezone_str[1:].split(':'))
        tz = timezone(timedelta(hours, minutes))
    else:
        raise ValueError(f"Invalid ISO-8601 time zone {timezone_str}")

    return datetime(year, month, day, hour, minute, second, microsecond, tz)

