def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    replacements = {}

    lines = text.split('\n')
    for line in lines:
        if not line.strip():
            continue

        if line.startswith('#'):
            line = line[1:]
            line = line.strip()
            if ':' in line:
                tag, value = line.split(':', 1)
                if value.strip() == 'true':
                    tags.add(tag.strip())
                else:
                    if replacer:
                        replacements[tag.strip()] = replacer(tag.strip())
                    else:
                        replacements[tag.strip()] = tag.strip()

    if replacements:
        for tag, value in replacements.items():
            text = text.replace(tag, value)

    return tags, text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re

    def extract_tag(text):
        m = re.search(r'#\s*(\w+)', text)
        if m:
            return m.group(1)
        return None

    if text is None:
        return set(), ''

    ignore_tags = {'def', 'class', 'if', 'else', 'while', 'for', 'else', 'try', 'except', 'finally', 'with', 'as', 'def', 'class'}
    lines = text.split('\n')
    new_text = ''
    tags = set()

    for line in lines:
        tag = extract_tag(line)
        if tag and tag not in ignore_tags:
            match = re.search(r'replace_:\s*(\w+)', line)
            if match:
                tag = match.group(1)
                if callable(replacer):
                    text = text.replace(tag, replacer(tag))
            tags.add(tag)
        new_text += line + '\n'

    return tags, new_text

