    for i, line in enumerate(lines):
        # Find all occurrences of tags or placeholders in the line
        tags_found = re.findall(r'\$tags|<[^\s<>]+>|\s+$', line)

        # Iterate over the found tags
        for tag in tags_found:
            # Remove any leading/trailing whitespace around tags
            tag = tag.strip()

            # Check if the tag is inside a code block
            inside_code_block = False
            if tag.startswith('$code') and tag.endswith('$code'):
                inside_code_block = True

            # Skip checking inside code blocks
            if inside_code_block:
                continue

            # Extract the tag if there is no placeholder
            if tag.startswith('$tags'):
                tag = tag[6:]

            # Check if a replacer function is provided
            if replacer is not None:
                # Replacer can be a string or a callable
                if isinstance(replacer, str):
                    tag = replacer.format(tag)
                elif callable(replacer):
                    tag = replacer(tag)

            # If the tag is not in any styles or the style is <no_style>, add it to the set
            if not any(tag.startswith(style) for style in ['<style>']):
                if not any(tag in style for style in ['<no_style>', '$code']):
                    tags.add(tag)

            # Replace the tag in the modified text
            if not inside_code_block:
                modified_text = modified_text.replace(tag, f'$tags[{i},{irunes}]', 1)

    # Return the set of tags and the modified text
    return tags, modified_text

