def verify_relayable_signature(public_key, doc, signature):
    # Attempt to parse the document
    try:
        root = ET.fromstring(doc)
    except ET.ParseError:
        raise ValueError("Invalid XML document")

    # Check if the xml is signed
    if root.tag in XSD_VALID_TAGS:
        try:
            root.getroot().validate(XSD_VALID_TREE)
        except ET.DocumentInvalid:
            raise ValueError(f"XML is not digitally signed ({root.tag})")

    # Check if the doc element is signed
    if doc.find(namespace + "Signature") is not None:
        try:
            validate_signature(public_key, doc, signature)
        except InvalidMessageSignature:
            raise ValueError("Message is not signed correctly")
    else:
        raise ValueError("No signature found in document")

    print("Signature verified successfully.")

