    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if "webfingerv2" in document:
        return parse_webfinger_v2(document)
    else:
        return parse_webfinger_v1(document)

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        # Check if the document is in JSON format
        if document.startswith("{"):
            data = json.loads(document)
            return data
        # Check if the document is in XRD format
        elif document.strip().lower().startswith("jsonld"):
            data = json.loads(document)
            return data
        else:
            raise ValueError("Unsupported format")
    except ValueError as e:
        print(f"Error parsing Diaspora webfinger: {e}")
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    if document.startswith("{"):  # JSON format
        try:
            return json.loads(document)
        except json.JSONDecodeError as e:
            return {"error": str(e)}
    elif document.startswith("fd-event: "):  # XRD format
        try:
            document = document.replace("fd-event: ", "")
            rels = document.split('rel="')[1].strip('"')
            if rels == "http://microformats.org/impp":
                return {"email": document.split('@')[0]}
            elif rels == "http://xmlns.diaspora.org/ns/hcard":
                return {"hcard_url": document}
            else:
                return {"error": "Unsupported rel value"}
        except IndexError:
            return {"error": "Invalid XRD document"}
    else:
        return {"error": "Unsupported content type"}

