def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    playbook = ir_workspace.playbook
    if playbook is None:
        raise ValueError("No playbook specified")

    verbosity = "-vvvvv" if vars_dict.get('debug', False) else "-v"
    command = ["ansible-playbook", verbosity, playbook]

    for param, value in vars_dict.items():
        key = "--{param}".format(param=param)
        if isinstance(value, list):
            value = " ".join([str(i) for i in value])
        key_value = key + "={value}".format(value=value)
        command.append(key_value)

    logger.debug("Executing Ansible call '%s' with vars %s", " ".join(command), vars_dict)
    p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = p.communicate()
    if p.returncode != 0:
        raise RuntimeError("Ansible reported an error when executing playbook %s" % playbook)
    return stdout.decode('utf-8')

